cat > app.test.mjs <<'EOF'
import test from 'node:test';
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';

function exportRow(values, variant) {
  return execFileSync(process.execPath, [
    new URL('./app.mjs', import.meta.url).pathname,
    JSON.stringify(values),
    ...(variant ? [variant] : []),
  ], {encoding: 'utf8'});
}

test('default preserves Unicode and column order while escaping CSV fields', () => {
  assert.equal(
    exportRow(['Zoë', '東京', 'Lee, Sam', 'say "hi"', 'line\nbreak', 'carriage\rreturn', 'both\r\nbreaks', '', 'last']),
    'Zoë,東京,"Lee, Sam","say ""hi""","line\nbreak","carriage\rreturn","both\r\nbreaks",,last\n',
  );
});

test('empty fields, repeated fields, and scalar conversions retain their positions', () => {
  assert.equal(exportRow(['', 0, false, null, 'same', 'same', '']), ',0,false,null,same,same,\n');
  assert.equal(exportRow([]), '\n');
});

test('explicit full configuration matches the default', () => {
  const values = ['東京', 'a,b', '"', '\r\n'];
  assert.equal(exportRow(values, 'full'), exportRow(values));
});

test('component configurations remain available', () => {
  const values = ['Zoë', 'a,b', '"'];
  assert.equal(exportRow(values, 'baseline'), 'Zo,a,b,"\n');
  assert.equal(exportRow(values, 'without-unicode'), 'Zo,"a,b",""""\n');
  assert.equal(exportRow(values, 'without-escaping'), 'Zoë,a,b,"\n');
});
EOF
